Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "dataset"
  },
  "transform": [
    {
      "calculate": "datum[''Negative Rate''] * datum[''Total Reviews'']",
      "as": "neg_count"
    }
  ],
  "hconcat": [
    {
      "width": 190,
      "height": 130,
      "layer": [
        {
          "mark": {
            "type": "text",
            "align": "left",
            "baseline": "top",
            "x": 0,
            "y": 0,
            "fontSize": 11,
            "color": "#8A7F6E",
            "text": "NEGATIVE REVIEWS",
            "letterSpacing": 1.5
          },
          "transform": [
            {
              "aggregate": [
                {
                  "op": "count",
                  "as": "n"
                }
              ]
            }
          ]
        },
        {
          "mark": {
            "type": "text",
            "align": "left",
            "baseline": "top",
            "x": 0,
            "y": 22,
            "fontSize": 34,
            "color": "#AD2F4B",
            "fontWeight": 600
          },
          "transform": [
            {
              "aggregate": [
                {
                  "op": "sum",
                  "field": "neg_count",
                  "as": "p"
                },
                {
                  "op": "sum",
                  "field": "Total Reviews",
                  "as": "t"
                }
              ]
            },
            {
              "calculate": "datum.p / datum.t",
              "as": "rate"
            }
          ],
          "encoding": {
            "text": {
              "field": "rate",
              "format": ".1%"
            }
          }
        },
        {
          "mark": {
            "type": "text",
            "align": "left",
            "baseline": "top",
            "x": 0,
            "y": 76,
            "fontSize": 12,
            "color": "#AD2F4B",
            "fontWeight": 600
          },
          "transform": [
            {
              "filter": "datum[''Total Reviews''] > 1000"
            },
            {
              "joinaggregate": [
                {
                  "op": "max",
                  "field": "Negative Rate",
                  "as": "hi"
                }
              ]
            },
            {
              "filter": "datum[''Negative Rate''] == datum.hi"
            },
            {
              "calculate": "''Highest '' + datum.Year + '': '' + format(datum[''Negative Rate''], ''.1%'')",
              "as": "t"
            }
          ],
          "encoding": {
            "text": {
              "field": "t"
            }
          }
        },
        {
          "mark": {
            "type": "text",
            "align": "left",
            "baseline": "top",
            "x": 0,
            "y": 96,
            "fontSize": 12,
            "color": "#6B6255"
          },
          "transform": [
            {
              "filter": "datum[''Total Reviews''] > 1000"
            },
            {
              "joinaggregate": [
                {
                  "op": "min",
                  "field": "Negative Rate",
                  "as": "lo"
                }
              ]
            },
            {
              "filter": "datum[''Negative Rate''] == datum.lo"
            },
            {
              "calculate": "''Lowest '' + datum.Year + '': '' + format(datum[''Negative Rate''], ''.1%'')",
              "as": "t"
            }
          ],
          "encoding": {
            "text": {
              "field": "t"
            }
          }
        }
      ]
    },
    {
      "width": 340,
      "height": 130,
      "transform": [
        {
          "filter": "datum[''Total Reviews''] > 1000"
        }
      ],
      "encoding": {
        "x": {
          "field": "Year",
          "type": "ordinal",
          "axis": {
            "title": null,
            "labelAngle": 0,
            "domain": false,
            "ticks": false,
            "labelColor": "#8A7F6E",
            "labelFontSize": 10,
            "labelExpr": "\"''\" + substring(datum.label, 2)"
          }
        },
        "y": {
          "field": "Negative Rate",
          "type": "quantitative",
          "scale": {
            "zero": false
          },
          "axis": null
        }
      },
      "layer": [
        {
          "mark": {
            "type": "area",
            "interpolate": "monotone",
            "color": {
              "x1": 0,
              "y1": 0,
              "x2": 0,
              "y2": 1,
              "gradient": "linear",
              "stops": [
                {
                  "offset": 0,
                  "color": "rgba(173,47,75,0.35)"
                },
                {
                  "offset": 1,
                  "color": "rgba(173,47,75,0)"
                }
              ]
            }
          }
        },
        {
          "mark": {
            "type": "line",
            "interpolate": "monotone",
            "strokeWidth": 3,
            "color": {
              "x1": 0,
              "y1": 0,
              "x2": 1,
              "y2": 0,
              "gradient": "linear",
              "stops": [
                {
                  "offset": 0,
                  "color": "#E8833A"
                },
                {
                  "offset": 1,
                  "color": "#AD2F4B"
                }
              ]
            }
          }
        },
        {
          "transform": [
            {
              "window": [
                {
                  "op": "rank",
                  "as": "r"
                }
              ],
              "sort": [
                {
                  "field": "Year",
                  "order": "descending"
                }
              ]
            },
            {
              "filter": "datum.r == 1"
            }
          ],
          "mark": {
            "type": "point",
            "filled": true,
            "size": 70,
            "color": "#F2B632",
            "stroke": "#FFFFFF",
            "strokeWidth": 2
          }
        },
        {
          "mark": {
            "type": "point",
            "opacity": 0,
            "size": 200
          },
          "encoding": {
            "tooltip": [
              {
                "field": "Year"
              },
              {
                "field": "Negative Rate",
                "title": "Negative",
                "format": ".1%"
              },
              {
                "field": "Total Reviews",
                "title": "Reviews",
                "format": ","
              }
            ]
          }
        }
      ]
    }
  ],
  "spacing": 16,
  "config": {
    "view": {
      "stroke": null
    },
    "font": "Segoe UI"
  }
}'
